"use client";
import Image from "next/image";
import AnimatedGradientBackground from "./Gredient";
import { useState, useEffect, useCallback, useMemo } from "react";
import { WordWithLogoRotate } from "./ui/text-rotate";
import { MousePointer2, Crown, ChevronLeft, ChevronRight, Heart, Copy, Rocket } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { formatWalletAddress } from "@/lib/wallet-privy";
import { useWallets } from "@privy-io/react-auth";
import { toast } from "sonner";
import Link from "next/link";

const platforms = [
  { name: "Replit", logo: "/companylogos/replit.svg" },
  { name: "Lovable", logo: "/companylogos/loveable.svg" },
  { name: "v0", logo: "/companylogos/v0.svg" },
  { name: "Bolt", logo: "/companylogos/bolt.svg" },
  { name: "Emergent", logo: "/companylogos/emargent.svg" },
];

interface BackendPresale {
  _id: string;
  appName?: string;
  appLogo?: string | null;
  tickerName?: string;
  description?: string;
  totalRaised?: string;
  erc20Symbol?: string;
  erc20Name?: string;
  appXHandle?: string;
  isXConnected?: boolean;
  network?: string;
  contributorCount?: number;
  creator?: string;
  contractStartTime?: number;
  endTime?: number;
  isActive?: boolean;
  poolCreated?: boolean;
  finalized?: boolean;
  heartCount?: number;
  heartUsers?: string[];
  presaleStatus?: string;
  [key: string]: any;
}

interface PresaleProject {
  id: string;
  title: string;
  erc20Name?: string;
  erc20Symbol?: string;
  description: string;
  appLogo: string | null;
  totalRaisedUSDC: string;
  softcap: string;
  contributorCount: number;
  creator?: string;
  startTime?: number;
  endTime?: number;
  presaleStatus?: string;
  heartCount: number;
  heartUsers: string[];
}

// Format USDC amount (divide by 1e6 since USDC has 6 decimals)
const formatUSDC = (weiString: string | undefined): string => {
  if (!weiString) return "0";
  try {
    const wei = BigInt(weiString);
    const usdc = Number(wei) / 1e6;
    return usdc.toFixed(2);
  } catch {
    return "0";
  }
};

export default function HeroSectionPresales() {
  const [currentCardIndex, setCurrentCardIndex] = useState(0);
  const [topPresales, setTopPresales] = useState<PresaleProject[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { wallets } = useWallets();
  const connectedWalletAddress = wallets[0]?.address || null;

  // Fetch top presales from backend
  const fetchTopPresales = useCallback(async () => {
    try {
      const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:3001";
      const res = await fetch(`${backendUrl}/api/presales`, {
        cache: "no-store",
      });

      if (!res.ok) {
        throw new Error("Failed to fetch presales");
      }

      const data = await res.json();
      const presales: BackendPresale[] = data.data || [];

      const now = Math.floor(Date.now() / 1000);

      // Filter for FUNDING presales
      let fundingPresales = presales.filter((p) => {
        const startTime = p.contractStartTime;
        const endTime = p.endTime;
        if (!startTime || !endTime) return false;
        return startTime <= now && endTime > now;
      });

      // If no FUNDING presales, fall back to ALL presales
      if (fundingPresales.length === 0) {
        fundingPresales = presales;
      }

      // Map to PresaleProject format
      const mappedPresales: PresaleProject[] = fundingPresales.map((presale) => {
        const totalRaisedUSDC = formatUSDC(presale.totalRaised);
        const softcap = "3000"; // Fixed value

        // Build logo URL
        let appLogo: string | null = null;
        if (presale.appLogo) {
          if (presale.appLogo.startsWith("http")) {
            appLogo = presale.appLogo;
          } else {
            const logoPath = presale.appLogo.startsWith("/") ? presale.appLogo : `/${presale.appLogo}`;
            appLogo = `${backendUrl}${logoPath}`;
          }
        }

        return {
          id: presale._id,
          title: presale.appName || presale.tickerName || "Untitled",
          erc20Name: presale.erc20Name,
          erc20Symbol: presale.erc20Symbol,
          description: presale.description || "",
          appLogo,
          totalRaisedUSDC,
          softcap,
          contributorCount: presale.contributorCount || 0,
          creator: presale.creator,
          startTime: presale.contractStartTime,
          endTime: presale.endTime,
          presaleStatus: presale.presaleStatus,
          heartCount: presale.heartCount || 0,
          heartUsers: presale.heartUsers || [],
        };
      });

      // Sort by totalRaisedUSDC descending
      mappedPresales.sort((a, b) => {
        const aRaised = parseFloat(a.totalRaisedUSDC);
        const bRaised = parseFloat(b.totalRaisedUSDC);
        return bRaised - aRaised;
      });

      // Take top 3
      const top3 = mappedPresales.slice(0, 3);
      setTopPresales(top3);

      // Reset carousel index if current index is out of bounds
      if (currentCardIndex >= top3.length) {
        setCurrentCardIndex(0);
      }
    } catch (error) {
      console.error("Error fetching top presales:", error);
    } finally {
      setIsLoading(false);
    }
  }, [currentCardIndex]);

  // Fetch on mount and set up polling
  useEffect(() => {
    fetchTopPresales();
    // Poll every 60 seconds for real-time updates
    const interval = setInterval(fetchTopPresales, 60000);
    return () => clearInterval(interval);
  }, [fetchTopPresales]);

  // Auto-rotate carousel
  useEffect(() => {
    if (topPresales.length <= 1) return;
    const interval = setInterval(() => {
      setCurrentCardIndex((prev) => (prev + 1) % topPresales.length);
    }, 5000); // Rotate every 5 seconds
    return () => clearInterval(interval);
  }, [topPresales.length]);

  const currentPresale = topPresales[currentCardIndex];

  // Calculate progress toward softcap
  const progressPercent = useMemo(() => {
    if (!currentPresale?.totalRaisedUSDC || !currentPresale?.softcap) return 0;
    const raised = parseFloat(currentPresale.totalRaisedUSDC);
    const cap = parseFloat(currentPresale.softcap);
    if (cap <= 0) return 0;
    return Math.min((raised / cap) * 100, 100);
  }, [currentPresale]);

  // Calculate time elapsed progress
  const PRESALE_DURATION = 360; // Duration in seconds
  const endTime = currentPresale?.startTime ? currentPresale.startTime + PRESALE_DURATION : null;

  const timeProgressPercent = useMemo(() => {
    if (!currentPresale?.startTime) return 0;
    const now = Math.floor(Date.now() / 1000);
    const startTime = currentPresale.startTime;

    if (now < startTime) return 0;
    if (endTime && now >= endTime) return 100;

    const elapsed = now - startTime;
    const progress = (elapsed / PRESALE_DURATION) * 100;
    return Math.min(Math.max(progress, 0), 100);
  }, [currentPresale, endTime]);

  // Heart functionality
  const [localHeartCount, setLocalHeartCount] = useState(0);
  const [hasGivenHeart, setHasGivenHeart] = useState(false);
  const [isHeartLoading, setIsHeartLoading] = useState(false);

  useEffect(() => {
    if (currentPresale) {
      setLocalHeartCount(currentPresale.heartCount || 0);
      if (connectedWalletAddress && currentPresale.heartUsers) {
        setHasGivenHeart(
          currentPresale.heartUsers.some(
            (addr) => addr.toLowerCase() === connectedWalletAddress.toLowerCase()
          )
        );
      } else {
        setHasGivenHeart(false);
      }
    }
  }, [currentPresale, connectedWalletAddress]);

  const handleHeartClick = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!connectedWalletAddress) {
      toast.error("Please connect your wallet to give a heart");
      return;
    }

    if (hasGivenHeart || isHeartLoading || !currentPresale) {
      return;
    }

    const previousCount = localHeartCount;
    const previousHasGivenHeart = hasGivenHeart;
    setLocalHeartCount(previousCount + 1);
    setHasGivenHeart(true);
    setIsHeartLoading(true);

    try {
      const res = await fetch(`/api/presales/${currentPresale.id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          walletAddress: connectedWalletAddress,
        }),
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.error || "Failed to add heart");
      }

      const data = await res.json();
      if (data.data) {
        setLocalHeartCount(data.data.heartCount || previousCount + 1);
      }
    } catch (error: any) {
      setLocalHeartCount(previousCount);
      setHasGivenHeart(previousHasGivenHeart);
      toast.error(error.message || "Failed to add heart");
    } finally {
      setIsHeartLoading(false);
    }
  };

  const handlePrevious = () => {
    setCurrentCardIndex((prev) => (prev - 1 + topPresales.length) % topPresales.length);
  };

  const handleNext = () => {
    setCurrentCardIndex((prev) => (prev + 1) % topPresales.length);
  };

  if (isLoading) {
    return (
      <section className="relative w-full overflow-hidden pt-[50px] sm:pt-[60px] pb-[60px] sm:pb-[80px] lg:pb-[105px]">
        <div className="relative z-10 flex w-full flex-col items-center px-4 sm:px-6 md:px-8 lg:px-10">
          <div className="w-full max-w-[480px] h-[320px] xs:h-[360px] sm:h-[380px] md:h-[400px] lg:h-[420px] rounded-[12px] bg-white/5 animate-pulse" />
        </div>
      </section>
    );
  }

  if (topPresales.length === 0) {
    return null; // Don't show anything if no presales
  }

  return (
    <section className="relative w-full overflow-hidden pt-[50px] sm:pt-[60px] pb-[60px] sm:pb-[80px] lg:pb-[105px]">
      {/* Background gradient */}
      <AnimatedGradientBackground
        Breathing={false}
        startingGap={130}
        gradientShape="ellipse"
        gradientColors={[
          "#050505",
          "#050505",
          "#f5650c45",
          "#05050500",
          "#05050500",
        ]}
        gradientStops={[0, 40, 55, 75, 100]}
        positionX={50}
        positionY={120}
        containerClassName="-z-20"
      />

      {/* Globe behind cards */}
      <div className="pointer-events-none absolute inset-x-0 top-[20%] sm:top-[22%] lg:top-[31%] z-0 flex justify-center">
        <div className="relative aspect-square w-[200px] sm:w-[250px] lg:w-[400px] xl:w-[450px] mix-blend-screen">
          <Image
            src="/globew.svg"
            alt="Glowing globe"
            fill
            sizes="500px"
            className="object-contain"
            priority
          />
        </div>
      </div>

      {/* Floating side platform logos (desktop) */}
      <div className="pointer-events-none absolute inset-0 -z-0 hidden xl:block">
        {/* Lovable - Top Left */}
        <div className="absolute left-[5%] top-[15%] animate-physics-float-1">
          <div className="flex items-center gap-2 rounded-full bg-white/8 backdrop-blur-xl px-3 py-2 shadow-[0_8px_32px_rgba(255,255,255,0.1)] transition-all duration-300 hover:shadow-[0_12px_48px_rgba(255,255,255,0.2)] hover:scale-110">
            <div className="relative h-6 w-6 shrink-0 rounded-full overflow-hidden bg-white">
              <Image
                src="/companylogos/loveable.svg"
                alt="Lovable"
                fill
                className="object-contain p-0.5"
              />
            </div>
            <span className="text-sm font-medium text-white/90">Lovable</span>
          </div>
        </div>

        <div className="absolute left-[5.8%] top-[12.5%] animate-cursor-wiggle-1">
          <MousePointer2 className="h-5 w-5 text-[#FF1744] fill-[#FF1744] drop-shadow-[0_0_8px_rgba(255,23,68,0.6)]" />
        </div>

        {/* Emergent - Mid Left */}
        <div className="absolute left-[9%] top-[33%] animate-physics-float-2">
          <div className="flex items-center gap-2 rounded-full bg-white/8 backdrop-blur-xl px-3 py-2 shadow-[0_8px_32px_rgba(255,255,255,0.1)] transition-all duration-300 hover:shadow-[0_12px_48px_rgba(255,255,255,0.2)] hover:scale-110">
            <div className="relative h-6 w-6 shrink-0 rounded-full overflow-hidden bg-white">
              <Image
                src="/companylogos/emargent.svg"
                alt="Emergent"
                fill
                className="object-contain p-0.5"
              />
            </div>
            <span className="text-sm font-medium text-white/90">Emergent</span>
          </div>
        </div>

        <div className="absolute left-[12%] top-[36%] animate-cursor-wiggle-2">
          <MousePointer2 className="h-5 w-5 text-gray-300 fill-gray-300 drop-shadow-[0_0_6px_rgba(255,255,255,0.4)]" />
        </div>

        {/* Replit - Top Right */}
        <div className="absolute right-[5%] top-[12%] animate-physics-float-3">
          <div className="flex items-center gap-2 rounded-full bg-white/8 backdrop-blur-xl px-3 py-2 shadow-[0_8px_32px_rgba(255,255,255,0.1)] transition-all duration-300 hover:shadow-[0_12px_48px_rgba(255,255,255,0.2)] hover:scale-110">
            <div className="relative h-6 w-6 shrink-0 rounded-full overflow-hidden bg-white">
              <Image
                src="/companylogos/replit.svg"
                alt="Replit"
                fill
                className="object-contain p-0.5"
              />
            </div>
            <span className="text-sm font-medium text-white/90">Replit</span>
          </div>
        </div>

        <div className="absolute right-[4.4%] top-[15.9%] animate-cursor-wiggle-1-delay">
          <MousePointer2 className="h-5 w-5 text-orange-500 fill-orange-500 drop-shadow-[0_0_8px_rgba(249,115,22,0.6)]" />
        </div>

        {/* v0 - Mid Right */}
        <div className="absolute right-[16%] top-[20%] animate-physics-float-4">
          <div className="flex items-center gap-2 rounded-full bg-white/8 backdrop-blur-xl px-3 py-2 shadow-[0_8px_32px_rgba(255,255,255,0.1)] transition-all duration-300 hover:shadow-[0_12px_48px_rgba(255,255,255,0.2)] hover:scale-110">
            <div className="relative h-6 w-6 shrink-0 rounded-full overflow-hidden bg-white">
              <Image
                src="/companylogos/v0.svg"
                alt="v0"
                fill
                className="object-contain p-0.5"
              />
            </div>
            <span className="text-sm font-medium text-white/90">v0</span>
          </div>
        </div>

        <div className="absolute right-[16%] top-[23.5%] animate-cursor-wiggle-3">
          <MousePointer2 className="h-5 w-5 text-gray-300 fill-gray-300 drop-shadow-[0_0_6px_rgba(255,255,255,0.4)]" />
        </div>

        {/* Bolt - Bottom Right */}
        <div className="absolute right-[13.5%] top-[32%] animate-physics-float-5">
          <div className="flex items-center gap-2 rounded-full bg-white/8 backdrop-blur-xl px-3 py-2 shadow-[0_8px_32px_rgba(255,255,255,0.1)] transition-all duration-300 hover:shadow-[0_12px_48px_rgba(255,255,255,0.2)] hover:scale-110">
            <div className="relative h-6 w-6 shrink-0 rounded-full overflow-hidden bg-white">
              <Image
                src="/companylogos/bolt.svg"
                alt="Bolt"
                fill
                className="object-contain p-0.5"
              />
            </div>
            <span className="text-sm font-medium text-white/90">Bolt</span>
          </div>
        </div>

        <div className="absolute right-[13%] top-[36%] animate-cursor-wiggle-2-delay">
          <MousePointer2 className="h-5 w-5 text-gray-300 fill-gray-300 drop-shadow-[0_0_6px_rgba(255,255,255,0.4)]" />
        </div>
      </div>

      {/* Main content */}
      <div className="relative z-10 flex w-full flex-col items-center px-4 sm:px-6 md:px-8 lg:px-10">
        {/* Top banner */}
        <div className="mb-1 sm:mb-1 flex items-center max-w-[95vw] sm:max-w-[90vw] mx-auto rounded-full border border-white/10 bg-[#111]/80 px-2.5 py-1 sm:px-4 sm:py-1.5 text-[8px] xs:text-[9px] sm:text-[11px] font-medium text-white/80 backdrop-blur-md shadow-[0_0_20px_rgba(0,0,0,0.5)]">
          <span className="shrink-0 mr-1.5 sm:mr-2 inline-flex h-1.5 w-1.5 animate-pulse rounded-full bg-[#FF2D55] shadow-[0_0_8px_rgba(255,45,85,1)]" />
          <span className="tracking-wide text-center truncate sm:whitespace-normal">
            Turn your AI vibecoded projects into investable tokens and raise
            capital instantly.
          </span>
        </div>

        {/* Heading */}
        <div className="text-center relative z-20 w-full px-2 mb-8 sm:mb-10 md:mb-12 lg:mb-14">
          <h1 className="text-center text-white">
            <span
              className="block drop-shadow-2xl text-[28px] leading-[36px] xs:text-[32px] xs:leading-[40px] sm:text-[40px] sm:leading-[50px] md:text-[48px] md:leading-[60px] lg:text-[56px] lg:leading-[68px] tracking-normal font-semibold"
              style={{ fontFamily: "var(--font-poppins)" }}
            >
              <span className="font-pixelify">L</span>aunch.{" "}
              <span className="font-pixelify">T</span>okenize.{" "}
              <span className="font-pixelify">F</span>und{" "}
              <span className="font-pixelify">Y</span>our
            </span>
            <span
              className="block text-white/90 text-[28px] leading-[36px] xs:text-[32px] xs:leading-[40px] sm:text-[40px] sm:leading-[50px] md:text-[48px] md:leading-[60px] lg:text-[56px] lg:leading-[68px] tracking-[0.8px] font-semibold"
              style={{ fontFamily: "var(--font-poppins)" }}
            >
              <span className="font-pixelify">V</span>ibecoded{" "}
              <span className="font-pixelify">A</span>pp{" "}
              <span className="font-pixelify">B</span>uilt{" "}
              <span className="font-pixelify">O</span>n
            </span>
            <span
              className="flex items-center justify-center text-[28px] leading-[36px] xs:text-[32px] xs:leading-[40px] sm:text-[40px] sm:leading-[50px] md:text-[48px] md:leading-[60px] lg:text-[56px] lg:leading-[68px]"
              style={{ fontFamily: "var(--font-poppins)" }}
            >
              <WordWithLogoRotate items={platforms} />
            </span>
          </h1>

          {/* Description */}
          <p className="mt-4 sm:mt-5 md:mt-6 max-w-2xl mx-auto text-center text-[11px] xs:text-xs sm:text-sm lg:text-base text-white/80 font-light leading-[1.6] px-2 sm:px-4">
            Import your app from Lovable, Cursor, Replit, Bolt, or any
            vibecoding platform.
            <br className="hidden sm:block" />
            Mint a token. Share it. Grow your community. Fund your roadmap.
          </p>
        </div>

        {/* Cards row - The "Glass Window" Container */}
        <div className="mt-6 sm:mt-10 md:mt-12 lg:mt-16 w-full mb-6 sm:mb-8 md:mb-12 lg:mb-16">
          <div className="flex flex-col xl:flex-row gap-3 sm:gap-4 md:gap-6 lg:gap-8">
            {/* LEFT BLOCK: Semi-transparent glass container */}
            <div className="w-full xl:flex-1 rounded-[12px] lg:rounded-[12px] border border-white/10 bg-white/[0.03] backdrop-blur-[40px] p-3 sm:p-4 md:p-6 lg:p-8 shadow-[0_40px_120px_-20px_rgba(0,0,0,0.5)] relative overflow-hidden">
              <div className="absolute inset-0 pointer-events-none"></div>

              <div className="flex flex-col lg:flex-row gap-6 sm:gap-8 md:gap-10 lg:gap-12 h-full relative z-10">
                {/* Top of the hill Card */}
                <div className="w-full lg:w-auto lg:shrink-0">
                  <div className="h-full flex flex-col relative overflow-hidden group transition-all duration-500">
                    <div className="relative flex items-center justify-between z-10 mb-3 sm:mb-4 md:mb-5 lg:mb-6">
                      <div className="flex items-center gap-1.5 sm:gap-2 text-xs sm:text-sm font-medium text-[#f0f0f0]">
                        <Crown className="text-[#FFB347] w-5 h-5 sm:w-6 sm:h-6 md:w-7 md:h-7 lg:text-3xl" />
                        <span className="text-sm sm:text-base md:text-lg lg:text-xl xl:text-2xl">
                          Top of the hill this week
                        </span>
                      </div>
                    </div>

                    {/* Presale Card with card.png background */}
                    {currentPresale && (
                      <div className="relative w-full max-w-[480px] h-[320px] xs:h-[360px] sm:h-[380px] md:h-[400px] lg:h-[420px] flex item-end justify-end z-10 overflow-hidden">
                        {/* Card Background Image */}
                        <div className="absolute inset-0 overflow-hidden">
                          <Image
                            src="/card.png"
                            alt="Card background"
                            fill
                            priority
                            className="object-cover"
                          />
                        </div>

                        {/* Card Content */}
                        <div className="relative p-3 xs:p-4 sm:p-5 md:p-6 flex flex-col h-full">
                          {/* Header Row */}
                          <div className="flex items-start justify-between mb-2 sm:mb-3 md:mb-4">
                            <div className="flex items-center gap-2 sm:gap-3 md:gap-4">
                              {/* Profile Picture - App Logo */}
                              <div className="relative h-10 w-10 xs:h-12 xs:w-12 sm:h-14 sm:w-14 flex-none overflow-hidden rounded-full border-2 border-white/10">
                                {currentPresale.appLogo ? (
                                  <Image
                                    src={currentPresale.appLogo}
                                    alt={currentPresale.erc20Name || currentPresale.title}
                                    fill
                                    unoptimized={true}
                                    className="object-cover"
                                  />
                                ) : (
                                  <div className="absolute inset-0 bg-gradient-to-br from-[#1A1A1A] to-black flex items-center justify-center">
                                    <Rocket className="h-6 w-6 text-white/20" />
                                  </div>
                                )}
                              </div>
                              <div className="flex flex-col gap-0.5 sm:gap-1 md:gap-1.5">
                                {/* Project Name - erc20Name */}
                                <span className="text-base xs:text-lg sm:text-xl font-bold text-white tracking-tight">
                                  {currentPresale.erc20Name || currentPresale.title}
                                </span>
                                <div className="flex items-center gap-1.5 sm:gap-2 md:gap-3 flex-wrap">
                                  {/* Badge - erc20Symbol */}
                                  {currentPresale.erc20Symbol && (
                                    <span className="text-[10px] xs:text-xs sm:text-sm font-black text-[#FF8A3C] bg-[#FF8A3C]/10 px-1.5 sm:px-2 py-0.5 rounded-[4px] border border-[#FF8A3C]/20">
                                      {currentPresale.erc20Symbol}
                                    </span>
                                  )}
                                  <span className="text-gray-400 text-xs sm:text-sm">|</span>
                                  {/* Heart count */}
                                  <span className="flex items-center text-[10px] xs:text-xs sm:text-sm text-gray-300 font-medium gap-0.5 sm:gap-1">
                                    <span className="text-pink-400">♥</span> {localHeartCount}
                                  </span>
                                  {/* Person count - contributorCount */}
                                  <span className="flex items-center text-[10px] xs:text-xs sm:text-sm text-gray-300 font-medium gap-0.5 sm:gap-1">
                                    <span className="text-gray-400">👤</span>{" "}
                                    {currentPresale.contributorCount || 0}
                                  </span>
                                </div>
                              </div>
                            </div>
                            {/* Presale Status Badge */}
                            {currentPresale.presaleStatus && (
                              <div
                                className={`flex items-center justify-center px-2 xs:px-3 sm:px-4 py-1 sm:py-1.5 rounded-md text-[10px] xs:text-xs sm:text-sm font-bold text-white tracking-wider ${
                                  currentPresale.presaleStatus === "UPCOMING"
                                    ? "bg-yellow-500"
                                    : currentPresale.presaleStatus === "FUNDING"
                                    ? "bg-green-500"
                                    : currentPresale.presaleStatus === "Not Finalized"
                                    ? "bg-orange-500"
                                    : currentPresale.presaleStatus === "Failed"
                                    ? "bg-red-500"
                                    : currentPresale.presaleStatus === "Completed"
                                    ? "bg-yellow-400"
                                    : "bg-gray-500"
                                }`}
                              >
                                {currentPresale.presaleStatus}
                              </div>
                            )}
                          </div>

                          {/* Description */}
                          {currentPresale.description && (
                            <p className="text-[11px] xs:text-xs sm:text-sm leading-relaxed text-gray-300 font-medium line-clamp-2 mb-2 sm:mb-3">
                              {currentPresale.description.replace(/^<p>|<\/p>$/g, '').trim()}
                            </p>
                          )}

                          {/* Creator */}
                          {currentPresale.creator && (
                            <div className="flex items-center gap-1.5 sm:gap-2 text-[11px] xs:text-xs sm:text-sm text-gray-400 mb-2 sm:mb-3 md:mb-4">
                              <span>Creator</span>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  navigator.clipboard.writeText(currentPresale.creator!);
                                  toast.success("Address copied!");
                                }}
                                className="flex items-center gap-1.5 sm:gap-2 text-white hover:text-[#ea580c] transition-colors cursor-pointer group"
                              >
                                <span className="font-bold font-mono">
                                  {formatWalletAddress(currentPresale.creator)}
                                </span>
                                <Copy className="h-3 w-3 sm:h-3.5 sm:w-3.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                              </button>
                            </div>
                          )}

                          {/* Price (totalRaisedUSDC) and Cap (softcap) Row */}
                          <div className="flex items-end justify-between mb-2 sm:mb-3">
                            <div className="flex flex-col gap-0.5">
                              <span className="text-white text-[10px] xs:text-xs sm:text-sm font-semibold uppercase tracking-wider">
                                Total Raised USDC
                              </span>
                              <span className="font-bold text-white text-lg xs:text-xl sm:text-2xl tracking-tight">
                                ${currentPresale.totalRaisedUSDC || "0"}
                              </span>
                            </div>
                            <div className="flex flex-col items-end gap-0.5">
                              <span className="text-[10px] xs:text-xs sm:text-sm text-gray-400 font-medium tracking-wide">
                                Cap
                              </span>
                              <span className="text-sm xs:text-base sm:text-lg font-semibold text-[#22c55e]">
                                ${currentPresale.softcap || "3000"}
                              </span>
                            </div>
                          </div>

                          {/* Volume Progress Bar */}
                          <div className="h-1.5 sm:h-2 w-full overflow-hidden rounded-full bg-black/20 mb-2 sm:mb-3">
                            <motion.div
                              initial={{ width: 0 }}
                              animate={{ width: `${progressPercent}%` }}
                              transition={{ duration: 1, ease: "easeOut" }}
                              className="h-full rounded-full bg-gradient-to-r from-[#ea580c] to-[#fb923c] shadow-[0_0_12px_rgba(234,88,12,0.6)]"
                            />
                          </div>

                          {/* Time Progress Bar */}
                          <div className="mb-2 sm:mb-3">
                            <div className="flex items-center justify-between mb-1">
                              <div className="flex flex-col gap-0.5">
                                {currentPresale.startTime && (
                                  <span className="text-white text-[10px] xs:text-xs sm:text-sm font-semibold uppercase tracking-wider">
                                    {new Date(currentPresale.startTime * 1000).toLocaleDateString(undefined, {
                                      month: 'short',
                                      day: 'numeric',
                                      hour: '2-digit',
                                      minute: '2-digit',
                                    })}
                                  </span>
                                )}
                              </div>
                              <div className="flex flex-col items-end gap-0.5">
                                {endTime && (
                                  <span className="text-white text-[10px] xs:text-xs sm:text-sm font-semibold uppercase tracking-wider text-right">
                                    {new Date(endTime * 1000).toLocaleDateString(undefined, {
                                      month: 'short',
                                      day: 'numeric',
                                      hour: '2-digit',
                                      minute: '2-digit',
                                    })}
                                  </span>
                                )}
                              </div>
                            </div>
                            <div className="h-1 sm:h-1.5 w-full overflow-hidden rounded-full bg-black/20 mb-2 sm:mb-3">
                              <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: `${timeProgressPercent}%` }}
                                transition={{ duration: 1, ease: "easeOut" }}
                                className="h-full rounded-full bg-gradient-to-r from-[#ea580c] to-[#fb923c] shadow-[0_0_12px_rgba(234,88,12,0.6)]"
                              />
                            </div>
                          </div>

                          {/* Bottom Section: Buttons & Chart */}
                          <div className="flex items-end justify-between mt-auto gap-2">
                            {/* Left Side: Buttons */}
                            <div className="flex flex-col gap-2 sm:gap-3">
                              {/* $[erc20Symbol] button */}
                              {currentPresale.erc20Symbol && (
                                <button className="rounded-full border-2 border-[#ea580c] bg-transparent px-3 xs:px-4 sm:px-5 md:px-6 py-1.5 sm:py-2 text-xs xs:text-sm sm:text-base font-bold text-[#ea580c] transition-all hover:bg-[#ea580c]/10">
                                  ${currentPresale.erc20Symbol}
                                </button>
                              )}
                              {/* View token link */}
                              <Link
                                href={`/presale/${currentPresale.id}`}
                                className="text-xs xs:text-sm sm:text-base font-bold text-[#ea580c] hover:text-[#ea580c] transition-colors tracking-wide"
                                onClick={(e) => e.stopPropagation()}
                              >
                                View token
                              </Link>
                            </div>

                            {/* Right Side: Chart/Graph and Heart Icon */}
                            <div className="flex flex-col items-end gap-2">
                              {/* Chart/Graph */}
                              <div className="relative w-[120px] h-[60px] xs:w-[140px] xs:h-[70px] sm:w-[160px] sm:h-[75px] md:w-[180px] md:h-[80px]">
                                <svg width="100%" height="100%" viewBox="0 0 100 50" className="overflow-visible">
                                  <defs>
                                    <linearGradient id="chartGradient-hero" x1="0%" y1="0%" x2="0%" y2="100%">
                                      <stop offset="0%" stopColor="#22c55e" stopOpacity="0.3" />
                                      <stop offset="100%" stopColor="#22c55e" stopOpacity="0" />
                                    </linearGradient>
                                  </defs>
                                  <path
                                    d="M 0,40 Q 20,35 40,30 T 80,20 T 100,15 L 100,50 L 0,50 Z"
                                    fill="url(#chartGradient-hero)"
                                  />
                                  <polyline
                                    points="0,40 20,35 40,30 60,25 80,20 100,15"
                                    fill="none"
                                    stroke="#22c55e"
                                    strokeWidth="2"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                  />
                                </svg>
                              </div>
                              {/* Heart Icon Button */}
                              <button
                                onClick={handleHeartClick}
                                disabled={hasGivenHeart || isHeartLoading || !connectedWalletAddress}
                                className={`flex items-center gap-1.5 px-2 py-1.5 rounded-lg transition-all ${
                                  hasGivenHeart
                                    ? "bg-pink-500/20 border border-pink-500/30 cursor-not-allowed"
                                    : connectedWalletAddress
                                    ? "bg-white/5 border border-white/10 hover:bg-pink-500/10 hover:border-pink-500/30 cursor-pointer"
                                    : "bg-white/5 border border-white/10 cursor-not-allowed opacity-50"
                                }`}
                              >
                                <Heart
                                  className={`h-4 w-4 ${
                                    hasGivenHeart ? "fill-pink-400 text-pink-400" : "text-gray-400"
                                  } ${isHeartLoading ? "animate-pulse" : ""}`}
                                />
                                <span className="text-[10px] xs:text-xs font-medium text-white">
                                  {localHeartCount}
                                </span>
                              </button>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Carousel Navigation */}
                    {topPresales.length > 1 && (
                      <div className="flex items-center justify-center gap-4 mt-4">
                        <button
                          onClick={handlePrevious}
                          className="p-2 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 transition-all"
                          aria-label="Previous presale"
                        >
                          <ChevronLeft className="h-5 w-5 text-white" />
                        </button>
                        <div className="flex gap-2">
                          {topPresales.map((_, index) => (
                            <button
                              key={index}
                              onClick={() => setCurrentCardIndex(index)}
                              className={`h-2 rounded-full transition-all ${
                                index === currentCardIndex
                                  ? "w-8 bg-[#ea580c]"
                                  : "w-2 bg-white/20 hover:bg-white/30"
                              }`}
                              aria-label={`Go to presale ${index + 1}`}
                            />
                          ))}
                        </div>
                        <button
                          onClick={handleNext}
                          className="p-2 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 transition-all"
                          aria-label="Next presale"
                        >
                          <ChevronRight className="h-5 w-5 text-white" />
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
